"""Implementation of actions for the treatment pane in the XVI application"""

from interops.libraries.squish_actions import CommonActions
from interops.libraries.xvi.interactions.objects.xvi_core_objects import Xvi_MainPage
from interops.libraries.xvi.interactions.objects.xvi_patient_objects import Xvi_Patient_page
from interops.libraries.xvi.interactions.objects.xvi_treatment_objects import Xvi_Treatment_page

def __find_treatment_window() -> bool:
    """Searches for the Treatment window of xvi. Returns True if successfully located.

    -> Hidden function that should not be used outside the context of the d_and_i.py file context!

    :return: True or False
    :rtype: bool
    """
    return True if CommonActions.find_object(Xvi_Treatment_page.treatment_Window) is not None else False

def __find_treatment_error_dialog() -> bool:
    """Searches for the Treatment error diolog of xvi. Returns True if successfully located.

    -> Hidden function that should not be used outside the context of the d_and_i.py file context!

    :return: True or False
    :rtype: bool
    """
    return True if CommonActions.find_object(Xvi_MainPage.intuity_XVI_Default_Database_dialog) is not None else False

def open_treatment_newPage() -> bool:
    """Open a new Treatment window from main menu
    :return: True or False
    :rtype: bool
    """
    CommonActions.left_click_object(Xvi_Patient_page.Patient_ListItem)
    CommonActions.left_click_object(Xvi_Treatment_page.treatment_New_button)
    return __find_treatment_window()

def typeText_in_treatement_id(treatmentID: str) -> None:
    """Locates the main New Treatment Registration window > types a given treatmentID string into the  treatmentID text box.

    :param str treatmentID: treatmentID string to be typed into the treatmentID text box
    """
    if __find_treatment_window():
         CommonActions.type_in_textfield(Xvi_Treatment_page.treatement_ID_edit,treatmentID)

def typeText_in_treatement_description(treatmentDescription: str) -> None:
    """Locates the main New Treatment Registration window > types a given treatmentDescription string into the  treatmentDescription text box.

    :param str treatmentDescription: treatmentDescription string to be typed into the first name text box
    """
    if __find_treatment_window():
         CommonActions.type_in_textfield(Xvi_Treatment_page.treatment_Description_Edit,treatmentDescription)

def select_orientation(treatmentOrientation: str) -> None:
    """select orientation from dropdown.

    :param str treatmentOrientation: treatmentOrientation string to be selected into the dropdown
    """
    if __find_treatment_window():
         CommonActions.left_click_object(Xvi_Treatment_page.treatment_Orientation_ComboBox)
         obj=CommonActions.get_child_objects(Xvi_Treatment_page.orientation_ComboBox)
         obj=CommonActions.get_child_object_by_object_text(obj,treatmentOrientation)
         CommonActions.left_click_object(obj)

def select_inactive() -> None:
    """select inactive checkbox
    """
    if __find_treatment_window():
        CommonActions.left_click_object(Xvi_Treatment_page.treatment_Inactive_CheckBox)

def clickOK() -> bool:
    """select inactive checkbox
    """
    if __find_treatment_window():
        CommonActions.left_click_object(Xvi_Treatment_page.treatment_OK_Button)
        if __find_treatment_error_dialog():
            CommonActions.left_click_object(Xvi_MainPage.intuity_XVI_Default_Database_XVI_OK_Button) #???
            CommonActions.left_click_object(Xvi_Treatment_page.treatment_Cancel_Button)
    return True if CommonActions.wait_for_object_to_disappear(Xvi_Treatment_page.treatment_Window) is not None else False